### 4. Implement AWS Secrets Manager

```javascript
// config/secrets.js - Production secrets manager
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
  }

  async getSecret(secretName, options = {}) {
    const { useCache = true, ttl = 300000 } = options; // 5 min default TTL

    // Check cache first
    if (useCache && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < ttl) {
        return cached.value;
      }
    }

    // Fetch from AWS Secrets Manager
    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secret;
      if (response.SecretString) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = JSON.parse(Buffer.from(response.SecretBinary).toString());
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        console.error(`Secret not found: ${secretName}`);
      } else {
        console.error('Error fetching secret:', error);
      }
      throw error;
    }
  }

  // Get multiple secrets in parallel
  async getSecrets(secretNames) {
    return Promise.all(
      secretNames.map(name => this.getSecret(name))
    );
  }
}

module.exports = new SecretsManager();
