// SECURE SECRETS MANAGEMENT EXAMPLE
// This file demonstrates proper secret management patterns

// ===========================================================================
// PATTERN 1: AWS Secrets Manager (Recommended for AWS)
// ===========================================================================

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class AWSSecretsManager {
  constructor(options = {}) {
    this.client = new SecretsManagerClient({
      region: options.region || process.env.AWS_REGION || 'us-east-1',
      ...(options.endpoint && { endpoint: options.endpoint })
    });
    this.cache = new Map();
    this.defaultTTL = options.cacheTTL || 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, options = {}) {
    const { forceRefresh = false, ttl = this.defaultTTL } = options;

    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && !forceRefresh && Date.now() - cached.timestamp < ttl) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secret;
      if (response.SecretString) {
        try {
          secret = JSON.parse(response.SecretString);
        } catch {
          secret = response.SecretString; // Not JSON, return as-is
        }
      } else if (response.SecretBinary) {
        secret = Buffer.from(response.SecretBinary, 'base64');
      }

      // Cache successfully retrieved secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        console.error(`Secret not found: ${secretName}`);
      } else if (error.name === 'AccessDeniedException') {
        console.error(`Access denied to secret: ${secretName}`);
      } else {
        console.error(`Error fetching secret ${secretName}:`, error.message);
      }
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  async getSecretValue(key, secretName, options = {}) {
    const secret = await this.getSecret(secretName, options);

    if (!secret) return null;

    if (typeof secret === 'object' && key in secret) {
      return secret[key];
    }

    if (typeof secret === 'string' && key === 'value') {
      return secret;
    }

    return null;
  }

  // Rotate cache on secret rotation events
  invalidateCache(secretName) {
    if (secretName) {
      this.cache.delete(secretName);
    } else {
      this.cache.clear();
    }
  }
}

// ===========================================================================
// PATTERN 2: Environment Variables with Validation (12-Factor)
// ===========================================================================

class EnvSecrets {
  constructor(config = {}) {
    this.required = config.required || [];
    this.optional = config.optional || [];
  }

  validate() {
    const missing = [];
    const warnings = [];

    // Check required secrets
    this.required.forEach(({ key, description }) => {
      if (!process.env[key]) {
        missing.push({ key, description: description || key });
      }
    });

    // Check optional secrets but log warnings
    this.optional.forEach(({ key, description }) => {
      if (!process.env[key]) {
        warnings.push({ key, description: description || key });
      }
    });

    if (missing.length > 0) {
      const missingStr = missing.map(m => `${m.key} (${m.description})`).join(', ');
      throw new Error(`Missing required secrets: ${missingStr}`);
    }

    if (warnings.length > 0 && process.env.NODE_ENV !== 'test') {
      console.warn('Optional secrets not configured:', 
        warnings.map(w => w.key).join(', '));
    }

    return { missing, warnings };
  }

  get(key, defaultValue = null) {
    return process.env[key] || defaultValue;
  }

  getAll() {
    const secrets = {};

    this.required.forEach(({ key }) => {
      secrets[key] = process.env[key];
    });

    this.optional.forEach(({ key }) => {
      secrets[key] = process.env[key];
    });

    return secrets;
  }
}

