// ===========================================================================

class ExternalSecretStore {
  constructor() {
    this.fetchers = new Map();
  }

  registerFetcher(name, fetcher) {
    this.fetchers.set(name, fetcher);
  }

  async getSecret(source, path, key) {
    const fetcher = this.fetchers.get(source);
    if (!fetcher) {
      throw new Error(`No fetcher registered for source: ${source}`);
    }
    return fetcher(path, key);
  }
}

