## Secret Rotation Strategy

### Pattern for Secure Rotation
```javascript
const { AWSSecretsManager } = require('./config.secrets-secure.example');
const secrets = new AWSSecretsManager();

class SecretWithRotation {
  constructor(secretName, secretKey, options = {}) {
    this.secretName = secretName;
    this.secretKey = secretKey;
    this.refreshInterval = options.refreshInterval || 24 * 60 * 60 * 1000; // 24 hours
    this.cachedValue = null;
    this.lastRefresh = 0;
  }

  async getValue() {
    const now = Date.now();

    // Refresh if cache expired
    if (this.cachedValue === null || now - this.lastRefresh > this.refreshInterval) {
      console.log(`Rotating secret: ${this.secretName}/${this.secretKey}`);
      this.cachedValue = await secrets.getSecretValue(this.secretKey, this.secretName, {
        forceRefresh: true
      });
      this.lastRefresh = now;
    }

    return this.cachedValue;
  }

  // Force rotation (can be called on compromise event)
  async forceRefresh() {
    this.lastRefresh = 0;
    return this.getValue();
  }
}

// Usage
const jwtSecret = new SecretWithRotation('production/app/config', 'jwt.secret', {
  refreshInterval: 4 * 60 * 60 * 1000 // 4 hours
});

app.use('/protected', async (req, res, next) => {
  const secret = await jwtSecret.getValue();
  // Use fresh secret for token validation
  next();
});
