class SecretManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache
    const cached = this.cache.get(secretName);
    if (cached && !forceRefresh && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      const secret = response.SecretString ? JSON.parse(response.SecretString) : null;

      // Cache the result
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      console.error(`Error fetching secret ${secretName}:`, error.message);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  async getSecretValue(key, secretName, forceRefresh = false) {
    const secret = await this.getSecret(secretName, forceRefresh);
    return secret ? secret[key] : null;
  }
}

const secrets = new SecretManager();

module.exports = { secrets };
