// Secure Express.js application with security best practices
// Implements OWASP security recommendations

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');
const { createLogger, transports, format } = require('winston');

const app = express();

// ============================================================================
// CONFIGURATION
// ============================================================================
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET || 'change-this-in-production-key';
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Security Headers (helmet)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Rate Limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => NODE_ENV === 'test' // Skip rate limiting in tests
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // More strict for auth endpoints
  message: 'Too many authentication attempts, please try again later.'
});

app.use(apiLimiter);

// 3. CORS Configuration
app.use(cors({
  origin: (origin, callback) => {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin) return callback(null, true);

    if (ALLOWED_ORIGINS.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400
}));

// 4. Request Logging
app.use(morgan('combined'));

// Security Logger
const securityLogger = createLogger({
  level: 'info',
  format: format.combine(
    format.timestamp(),
    format.json()
  ),
  transports: [
    new transports.Console(),
    new transports.File({ filename: 'security.log' })
  ]
});

// Log security events
const logSecurityEvent = (eventType, details) => {
  securityLogger.info({
    eventType,
    timestamp: new Date().toISOString(),
    ...details
  });
};

// ============================================================================
// INPUT VALIDATION & SANITIZATION
// ============================================================================

app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Validation middleware helper
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logSecurityEvent('validation_error', {
      ip: req.ip,
      errors: errors.array(),
      path: req.path
    });
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

// Generate JWT token (for demonstration)
const generateToken = (user) => {
  return jwt.sign(
    { id: user.id, role: user.role },
    JWT_SECRET,
    { expiresIn: '1h' }
  );
};

// Verify JWT token
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logSecurityEvent('auth_failure', {
      ip: req.ip,
      reason: 'No token provided',
      path: req.path
    });
    return res.status(401).json({ 
      error: 'Access token required',
      code: 'AUTH_TOKEN_MISSING'
    });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      logSecurityEvent('auth_failure', {
        ip: req.ip,
        reason: 'Invalid token',
        path: req.path
      });
      return res.status(403).json({ 
        error: 'Invalid or expired token',
        code: 'AUTH_TOKEN_INVALID'
      });
    }
    req.user = user;
    next();
  });
};

// Authorization middleware for admin-only routes
const requireAdmin = (req, res, next) => {
  if (req.user.role !== 'admin') {
    logSecurityEvent('authz_failure', {
      ip: req.ip,
      userId: req.user.id,
      attemptedRole: 'admin',
      path: req.path
    });
    return res.status(403).json({ 
      error: 'Admin access required',
      code: 'INSUFFICIENT_PERMISSIONS'
    });
  }
  next();
};

// ============================================================================
// ROUTES
// ============================================================================

// Health check endpoint (no auth required, rate limited)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

// Login endpoint (for demo purposes - use proper auth in production)
app.post('/auth/login', 
  strictLimiter,
  [
    body('username').trim().isLength({ min: 3, max: 50 }).escape(),
    body('password').isLength({ min: 8 })
  ],
  validate,
  (req, res) => {
    const { username, password } = req.body;

    // In production, verify against database with bcrypt
    // This is a simplified example
    if (username === 'admin' && password === 'securePassword123') {
      const token = generateToken({ id: 1, role: 'admin' });
      logSecurityEvent('login_success', {
        ip: req.ip,
        username,
        userId: 1
      });
      res.json({ token, user: { id: 1, username, role: 'admin' } });
    } else if (username === 'user' && password === 'password123') {
      const token = generateToken({ id: 2, role: 'user' });
      logSecurityEvent('login_success', {
        ip: req.ip,
        username,
        userId: 2
      });
      res.json({ token, user: { id: 2, username, role: 'user' } });
    } else {
      logSecurityEvent('login_failure', {
        ip: req.ip,
        username
      });
      res.status(401).json({ 
        error: 'Invalid credentials',
        code: 'AUTH_INVALID_CREDENTIALS'
      });
    }
  }
);

// Users endpoint - requires authentication
app.get('/users',
  authenticateToken,
  [
    query('limit').optional().isInt({ min: 1, max: 100 }),
    query('offset').optional().isInt({ min: 0 })
  ],
  validate,
  (req, res) => {
    logSecurityEvent('users_accessed', {
      ip: req.ip,
      userId: req.user.id,
      userRole: req.user.role
    });

    const { limit = 10, offset = 0 } = req.query;

    // Default users without sensitive data
    let users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    // Include email only for admin users
    if (req.user.role === 'admin') {
      users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];
    }

    // Apply pagination
    users = users.slice(offset, offset + limit);

    res.json({
      data: users,
      pagination: {
        limit,
        offset,
        total: users.length
      }
    });
  }
);

// Admin-only endpoint example
app.get('/admin/users',
  authenticateToken,
  requireAdmin,
  (req, res) => {
    logSecurityEvent('admin_users_accessed', {
      ip: req.ip,
      adminId: req.user.id
    });

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
    ];

    res.json({ data: users });
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

// 404 handler
app.use((req, res) => {
  logSecurityEvent('not_found', {
    ip: req.ip,
    path: req.path,
    method: req.method
  });
  res.status(404).json({ 
    error: 'Resource not found',
    code: 'NOT_FOUND'
  });
});

// Global error handler
app.use((err, req, res, next) => {
  securityLogger.error('Unhandled error', {
    error: err.message,
    stack: err.stack,
    ip: req.ip,
    path: req.path
  });

  // Don't leak error details in production
  const isDevelopment = NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'Internal Server Error',
      code: 'INTERNAL_ERROR',
      ...(isDevelopment && { stack: err.stack })
    }
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`🚀 Server running on port ${PORT}`);
    console.log(`📊 Environment: ${NODE_ENV}`);
    console.log(`🔒 Security: All middleware active`);

    if (NODE_ENV === 'development') {
      console.log('⚠️  Running in development mode - not for production use');
    }

    if (NODE_ENV === 'production') {
      console.warn('⚠️  Running in production mode - ensure:");
      console.warn('   - JWT_SECRET is set to a strong random value');
      console.warn('   - ALLOWED_ORIGINS is properly configured');
      console.warn('   - HTTPS is enabled (reverse proxy)');
      console.warn('   - Database credentials are secured');
    }
  });
}

module.exports = app;

