```javascript
// Install: npm install @aws-sdk/client-secrets-manager
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    this.cache = new Map();
  }

  async getSecret(secretName) {
    // Check cache first to avoid unnecessary API calls
    if (this.cache.has(secretName)) {
      return this.cache.get(secretName);
    }

    try {
      const response = await this.client.send(
        new GetSecretValueCommand({ SecretId: secretName })
      );

      const secret = response.SecretString;

      // Parse JSON if applicable
      const parsed = secret.includes('{') ? JSON.parse(secret) : secret;

      // Cache with 5-minute TTL
      this.cache.set(secretName, parsed);
      setTimeout(() => this.cache.delete(secretName), 5 * 60 * 1000);

      return parsed;
    } catch (error) {
      console.error(`Error fetching secret ${secretName}:`, error);
      throw new Error('Failed to retrieve secret');
    }
  }
}

// Usage in app.js
const secretsManager = new SecretsManager();

app.get('/users', async (req, res) => {
  const dbCredentials = await secretsManager.getSecret('production/db-credentials');
  // Use credentials to connect to database
  // ...
});
```

