```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const dotenv = require('dotenv');

// Load .env only in development
if (process.env.NODE_ENV !== 'production') {
  dotenv.config({ path: '.env.local' });
}

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });
    this.secretsCache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async loadSecrets() {
    const secretNames = [
      'prod/database/config',
      'prod/api/keys',
      'prod/payment/stripe',
    ];

    for (const name of secretNames) {
      await this.getSecret(name);
    }
  }

  async getSecret(secretName, forceRefresh = false) {
    const cached = this.secretsCache.get(secretName);
    const now = Date.now();

    // Return cached value if valid
    if (cached && !forceRefresh && (now - cached.timestamp < this.cacheTTL)) {
      return cached.value;
    }

    try {
      const response = await this.client.send(
        new GetSecretValueCommand({ SecretId: secretName })
      );

      const secret = JSON.parse(response.SecretString);
      this.secretsCache.set(secretName, {
        value: secret,
        timestamp: now,
      });

      return secret;
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      }
      throw error;
    }
  }

  // Individual secret accessors
  get databaseUrl() {
    return process.env.DATABASE_URL;
  }

  get jwtSecret() {
    return process.env.JWT_SECRET;
  }

  get awsCredentials() {
    return {
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    };
  }

  get stripeKey() {
    return process.env.STRIPE_SECRET_KEY;
  }

  get anthropicApiKey() {
    return process.env.ANTHROPIC_API_KEY;
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

// Validate required secrets on startup
function validateSecrets() {
  const required = [
    'DATABASE_URL',
    'JWT_SECRET',
    'STRIPE_SECRET_KEY',
  ];

  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }

  // Validate secret strength
  if (process.env.JWT_SECRET && process.env.JWT_SECRET.length < 32) {
    console.warn('⚠️  JWT_SECRET is too short. Use at least 32 characters.');
  }
}

module.exports = { secretsManager, validateSecrets };
```

