```javascript
// utils/fingerprint-secrets.js
const fs = require('fs');

function generateRotationManifest(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const manifest = {
    generatedAt: new Date().toISOString(),
    targetFile: filePath,
    secrets: []
  };

  const crypto = require('crypto');

  content.split('\n').forEach(line => {
    if (line.trim() && !line.startsWith('#')) {
      const [name, ...valueParts] = line.split('=');
      const value = valueParts.join('=').trim();

      if (name && value) {
        const prefix = value.substring(0, 4);
        const suffix = value.substring(value.length - 4);
        const hash = crypto.createHash('sha256').update(value).digest('hex').substring(0, 12);

        manifest.secrets.push({
          variable: name.trim(),
          fingerprint: `${prefix}***${suffix}_${hash}`,
          length: value.length,
          categories: categorizeSecret(value)
        });
      }
    }
  });

  return manifest;
}

function categorizeSecret(value) {
  const categories = [];
  if (value.includes('postgres:') || value.includes('postgresql:')) categories.push('connection-string');
  if (value.startsWith('sk_live_')) categories.push('live-api-key');
  if (value.startsWith('sk_test_')) categories.push('test-api-key');
  if (value.startsWith('sk-ant-')) categories.push('api-key');
  if (value.includes('CANARY')) categories.push('test-value');
  return categories;
}

