```javascript
// Install: npm install @aws-sdk/client-secrets-manager
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const secretsClient = new SecretsManagerClient({ 
  region: process.env.AWS_REGION || 'us-east-1' 
});

async function getSecret(secretName) {
  const command = new GetSecretValueCommand({ SecretId: secretName });
  const response = await secretsClient.send(command);

  if (response.SecretString) {
    return JSON.parse(response.SecretString);
  }
  throw new Error('Secret not found');
}

// Usage
async function initializeApp() {
  try {
    const dbSecrets = await getSecret('prod/database/credentials');
    const appSecrets = await getSecret('prod/app/keys');

    // Use secrets, never log them
    initializeDatabase(dbSecrets);
  } catch (error) {
    console.error('Failed to load secrets:', error.message);
    process.exit(1);
  }
}
```

**Benefits:**
- Encrypted at rest and in transit
- Automatic secret rotation
- Fine-grained IAM access policies
- Audit logging via CloudTrail

