```javascript
// Install dependencies
// npm install @aws-sdk/client-secrets-manager

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Initialize client outside of request handlers
const secretsClient = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1',
});

// Cache secrets with TTL to reduce API calls
let secretsCache = null;
let cacheExpiry = null;
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

async function getSecret(secretName) {
  // Check cache first
  if (secretsCache && Date.now() < cacheExpiry) {
    return secretsCache[secretName];
  }

  try {
    const command = new GetSecretValueCommand({
      SecretId: secretName,
    });

    const response = await secretsClient.send(command);
    const secret = JSON.parse(response.SecretString);

    // Update cache
    secretsCache = { [secretName]: secret };
    cacheExpiry = Date.now() + CACHE_TTL;

    return secret;
  } catch (error) {
    console.error(`Error fetching secret ${secretName}:`, error.message);
    throw new Error('Failed to retrieve credentials');
  }
}

// Initialize app with secrets
async function initializeApp() {
  try {
    const databaseSecrets = await getSecret('prod/database/credentials');
    const awsSecrets = await getSecret('prod/aws/credentials');
    const apiKeys = await getSecret('prod/api/keys');

    // Validate required secrets exist
    if (!databaseSecrets.username || !databaseSecrets.password) {
      throw new Error('Invalid database credentials structure');
    }

    // Construct database URL
    process.env.DATABASE_URL = `postgres://${databaseSecrets.username}:${databaseSecrets.password}@${databaseSecrets.host}:${databaseSecrets.port}/${databaseSecrets.dbname}`;
    process.env.AWS_ACCESS_KEY_ID = awsSecrets.accessKeyId;
    process.env.AWS_SECRET_ACCESS_KEY = awsSecrets.secretAccessKey;
    process.env.ANTHROPIC_API_KEY = apiKeys.anthropic;
    process.env.STRIPE_SECRET_KEY = apiKeys.stripe;

    console.log('Secrets loaded successfully');
    return true;
  } catch (error) {
    console.error('Failed to initialize secrets:', error.message);
    process.exit(1);
  }
}

// Export for use in app initialization
module.exports = { getSecret, initializeApp };
```

