// config/env.js
const path = require('path');
const fs = require('fs');

function loadEnvConfig() {
  const envPath = path.join(__dirname, '..', '.env');

  // Only load .env in non-production environments
  if (process.env.NODE_ENV === 'production') {
    throw new Error('.env files should not be used in production');
  }

  if (!fs.existsSync(envPath)) {
    throw new Error('.env file not found. Create one from .env.example');
  }

  require('dotenv').config({ path: envPath });

  // Validate all required secrets are present
  const requiredSecrets = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
  ];

  const missing = requiredSecrets.filter(key => !process.env[key]);

  if (missing.length > 0) {
    throw new Error(`Missing secrets: ${missing.join(', ')}`);
  }

  // Validate production URL isn't used in dev
  if (process.env.DATABASE_URL?.includes('production')) {
    throw new Error('Production credentials detected in development!');
  }

  return {
    databaseUrl: process.env.DATABASE_URL,
    awsKeyId: process.env.AWS_ACCESS_KEY_ID,
    awsSecret: process.env.AWS_SECRET_ACCESS_KEY,
    // ... other secrets
  };
}

module.exports = { loadEnvConfig };
