// secrets-rotator.js
class SecretsRotator {
  async rotateSecret(secretName) {
    console.log(`Rotating secret: ${secretName}`);

    // 1. Generate new secret
    const newSecret = this.generateSecret();

    // 2. Store both old and new (graceful period)
    await this.storeVersion(secretName, newSecret, 'v2');

    // 3. Wait for applications to pick up new secret
    await this.sleep(15 * 60 * 1000); // 15 minutes

    // 4. Remove old version
    await this.removeVersion(secretName, 'v1');

    console.log(`✓ Secret rotated: ${secretName}`);
