```javascript
// config/secrets.js
const AWS = require('aws-sdk');
const { NodeHttpHandler } = require('@smithy/node-http-handler');

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(name) {
    // Check cache first
    const cached = this.cache.get(name);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    let secretValue;

    if (process.env.NODE_ENV === 'production') {
      // Use AWS Secrets Manager in production
      secretValue = await this.getFromAWS(name);
    } else if (process.env.NODE_ENV === 'staging') {
      // Use AWS Parameter Store in staging
      secretValue = await this.getFromParameterStore(name);
    } else {
      // Use environment variables in development
      secretValue = process.env[name];
    }

    if (!secretValue) {
      throw new Error(`Secret not found: ${name}`);
    }

    // Cache the secret
    this.cache.set(name, {
      value: secretValue,
      timestamp: Date.now()
    });

    return secretValue;
  }

  async getFromAWS(secretName) {
    const client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    const data = await client.getSecretValue({ SecretId: secretName }).promise();

    if (data.SecretString) {
      return data.SecretString;
    } else {
      return Buffer.from(data.SecretBinary, 'base64').toString('utf-8');
    }
  }

  async getFromParameterStore(parameterName) {
    const ssm = new AWS.SSM({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    const result = await ssm.getParameter({
      Name: parameterName,
      WithDecryption: true
    }).promise();

    return result.Parameter.Value;
  }

  async loadAllSecrets() {
    const secretNames = [
      'DATABASE_URL',
      'JWT_SECRET',
      'STRIPE_SECRET_KEY',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'ANTHROPIC_API_KEY'
    ];

    const secrets = {};
    for (const name of secretNames) {
      try {
        secrets[name] = await this.getSecret(name);
      } catch (error) {
        console.error(`Failed to load secret ${name}:`, error.message);
        throw error;
      }
    }

    this.secrets = secrets;
    return secrets;
  }
}

module.exports = new SecretsManager();
```

