// app.js - Production secrets management approach
const AWS = require('aws-sdk');
const app = require('express')();

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.cache = {};
    this.cacheTTL = 300000; // 5 minutes
  }

  async loadSecrets() {
    // Only reload if cache is expired
    if (this.cache.expiry && Date.now() < this.cache.expiry) {
      return this.cache.data;
    }

    try {
      const client = new AWS.SecretsManager();

      // Fetch from AWS Secrets Manager
      const secret = await client.getSecretValue({
        SecretId: process.env.SECRET_ARN || 'prod/app-secrets'
      }).promise();

      this.cache = {
        data: JSON.parse(secret.SecretString),
        expiry: Date.now() + this.cacheTTL
      };

      return this.cache.data;
    } catch (error) {
      console.error('Failed to load secrets from Secrets Manager:', error);
      throw new Error('Unable to load application secrets');
    }
  }

  get(key) {
    if (this.cache.data && this.cache.data[key]) {
      return this.cache.data[key];
    }
    throw new Error(`Secret not found: ${key}`);
  }
}

const secretsManager = new SecretsManager();

// Middleware to inject secrets
app.use(async (req, res, next) => {
  if (!secretsManager.cache.data) {
    try {
      await secretsManager.loadSecrets();
    } catch (error) {
      // In development, fall back to environment variables
      if (process.env.NODE_ENV !== 'production') {
        console.warn('Falling back to environment variables');
        next();
        return;
      }
      return res.status(500).json({ error: 'Server configuration error' });
    }
  }
  req.secrets = secretsManager;
  next();
});

// Usage in routes
