// config/index.js
const NodeCache = require('node-cache');
const AWS = require('aws-sdk');

const secretsCache = new NodeCache({ stdTTL: 300 }); // 5 minute cache

async function getSecrets() {
  // Check cache first
  const cached = secretsCache.get('app-secrets');
  if (cached) return cached;

  let secrets;

  if (process.env.NODE_ENV === 'production') {
    // Use AWS Secrets Manager in production
    const secretsManager = new AWS.SecretsManager();
    const secretData = await secretsManager.getSecretValue({
      SecretId: process.env.SECRET_ARN || 'prod/app-secrets'
    }).promise();
    secrets = JSON.parse(secretData.SecretString);
  } else {
    // Use environment variables in development/staging
    secrets = {
      DATABASE_URL: process.env.DATABASE_URL,
      AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
      AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
      ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
      STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
      LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN
    };

    // Validate required secrets exist
    const required = ['DATABASE_URL', 'STRIPE_SECRET_KEY'];
    const missing = required.filter(key => !secrets[key]);
    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }

  // Cache the secrets
  secretsCache.set('app-secrets', secrets);
  return secrets;
}

module.exports = { getSecrets };
```

