### 3. Implement Secret Validation
```javascript
// config/secrets.js
class SecretsValidator {
  static validate() {
    const secrets = {
      database: {
        url: process.env.DATABASE_URL,
      },
      jwt: {
        secret: process.env.JWT_SECRET,
      },
    };

    const errors = [];

    if (!secrets.database.url) {
      errors.push('DATABASE_URL is required');
    }

    if (!secrets.jwt.secret || secrets.jwt.secret.length < 32) {
      errors.push('JWT_SECRET must be at least 32 characters');
    }

    // Check for canary/test values in production
    if (process.env.NODE_ENV === 'production') {
      Object.entries(secrets).forEach(([category, config]) => {
        Object.entries(config).forEach(([key, value]) => {
          if (value?.toLowerCase().includes('canary') || 
              value?.toLowerCase().includes('test_')) {
            errors.push(`PRODUCTION WARNING: ${category}.${key} appears to contain test values`);
          }
        });
      });
    }

    if (errors.length > 0) {
      throw new Error(`Secret validation failed:\n${errors.join('\n')}`);
    }

    return secrets;
  }
}

module.exports = SecretsValidator;
```

### 4. Startup Validation
```javascript
// app.js
const { app } = express();

try {
  const secrets = SecretsValidator.validate();
  app.locals.secrets = secrets;
  console.log('✓ Secrets loaded successfully');
} catch (error) {
  console.error(error.message);
  process.exit(1);
}
```

