```javascript
const { SSMClient, GetParameterCommand, GetParametersByPathCommand } = require('@aws-sdk/client-ssm');

const ssm = new SSMClient({ region: process.env.AWS_REGION || 'us-east-1' });

async function getParameter(name, decrypt = true) {
  const command = new GetParameterCommand({ 
    Name: name, 
    WithDecryption: decrypt 
  });

  const response = await ssm.send(command);
  return response.Parameter.Value;
}

async function getParametersByPath(path, decrypt = true) {
  const command = new GetParametersByPathCommand({ 
    Path: path, 
    WithDecryption: decrypt,
    Recursive: true
  });

  const response = await ssm.send(command);
  const result = {};

  response.Parameters.forEach(param => {
    const key = param.Name.split('/').pop();
    result[key] = param.Value;
  });

  return result;
}

async function loadAllParameters() {
  try {
    const appParams = await getParametersByPath('/myapp/production/');
    Object.assign(process.env, appParams);
    console.log('Parameters loaded successfully');
  } catch (error) {
    console.error('Failed to load parameters:', error);
    throw error;
  }
}

module.exports = { getParameter, getParametersByPath, loadAllParameters };
```

