### Production Secret Management Architecture

```javascript
// config/secret-loader.js
class SecretLoader {
  constructor() {
    this.cache = new Map();
    this.ttl = 300000; // 5 minute cache
  }

  async getSecret(name) {
    // Check cache first
    if (this.cache.has(name)) {
      const cached = this.cache.get(name);
      if (Date.now() - cached.timestamp < this.ttl) {
        return cached.value;
      }
    }

    let secretValue;

    if (process.env.NODE_ENV === 'production') {
      // Use AWS Secrets Manager in production
      secretValue = await this.getFromSecretsManager(name);
    } else {
      // Use .env in development
      secretValue = process.env[name];
    }

    if (!secretValue) {
      throw new Error(`Secret not found: ${name}`);
    }

    this.cache.set(name, { value: secretValue, timestamp: Date.now() });
    return secretValue;
  }

  async getFromSecretsManager(secretName) {
    const AWS = require('aws-sdk');
    const secretsManager = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    try {
      const data = await secretsManager.getSecretValue({
        SecretId: secretName
      }).promise();

      if (data.SecretString) {
        return data.SecretString;
      }
      return Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    } catch (error) {
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }
}

module.exports = new SecretLoader();
```

