    const secret = data.SecretString;

    // Parse JSON secrets if applicable
    const parsedSecret = secret.startsWith('{') 
      ? JSON.parse(secret) 
      : { value: secret };

    // Update cache
    if (!secretsCache || Date.now() >= cacheExpiry) {
      secretsCache = {};
      cacheExpiry = Date.now() + CACHE_TTL;
    }
    secretsCache[secretName] = parsedSecret;

    return parsedSecret;
  } catch (error) {
