app.use(helmet({
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"]
    }
  }
}));

// === Body Parser with Limits ===
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// === CORS Configuration ===
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || [],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400
}));

// === Rate Limiting ===
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later' }
});
app.use('/api/', limiter);

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: { error: 'Too many authentication attempts' }
});

// === Logging ===
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

app.use(morgan('combined', {
  skip: (req, res) => res.statusCode < 400
}));

// === Database Connection ===
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.NODE_ENV === 'production' 
    ? { rejectUnauthorized: true } 
    : false,
  max: 20,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000
});

// === Authentication Middleware ===
const authMiddleware = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const token = authHeader.split(' ')[1];

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET, {
      algorithms: ['HS256'],
      maxAge: '1h'
    });
    req.user = decoded;
    next();
  } catch (err) {
    logger.warn('Authentication failed', { 
      error: err.message, 
      ip: req.ip 
    });
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// === Input Validation ===
const { body, query, validationResult } = require('express-validator');

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed', 
      details: errors.array() 
    });
  }
  next();
};

// === Sanitization ===
const sanitizeUser = (user) => {
  const { id, name, created_at } = user;
  return { id, name, created_at };
};

// === Error Handler ===
const errorHandler = (err, req, res, next) => {
  logger.error('Unhandled error', {
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't leak stack traces in production
  const response = {
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message
  };

  res.status(err.status || 500).json(response);
};

app.use(errorHandler);

// === Routes ===

app.get('/health', (req, res) => {
  res.status(200).json({ status: 'healthy' });
});

app.get('/api/users', 
  authMiddleware, 
  handleValidationErrors,
  async (req, res) => {
    try {
      logger.info('User list accessed', {
        userId: req.user.id,
        role: req.user.role,
        ip: req.ip
      });

      // Authorization check - only admins can see the full list
      if (req.user.role !== 'admin') {
        return res.status(403).json({ error: 'Forbidden' });
      }

      const result = await pool.query(
        'SELECT id, name, email FROM users WHERE is_active = true ORDER BY id LIMIT 100'
      );

      res.json({
        data: result.rows.map(sanitizeUser),
        count: result.rows.length
      });
    } catch (err) {
      logger.error('Database query failed', { error: err.message });
      res.status(500).json({ error: 'Failed to retrieve users' });
    }
  }
);

// === Secure Server Startup ===
const HOST = process.env.HOST || '127.0.0.1';
const PORT = parseInt(process.env.PORT || '3000', 10);

if (process.env.NODE_ENV === 'production') {
  const https = require('https');
  const fs = require('fs');

  const sslOptions = {
    key: fs.readFileSync(path.join(__dirname, 'ssl', 'key.pem')),
    cert: fs.readFileSync(path.join(__dirname, 'ssl', 'cert.pem')),
    minVersion: 'TLSv1.2'
  };

  https.createServer(sslOptions, app).listen(PORT, HOST, () => {
    logger.info(`Secure server running on https://${HOST}:${PORT}`);
  });
} else {
  app.listen(PORT, HOST, () => {
    logger.info(`Server running on http://${HOST}:${PORT}`);
  });
}

// === Graceful Shutdown ===
const gracefulShutdown = async (signal) => {
  logger.info(`${signal} received, starting graceful shutdown`);

  // Stop accepting new connections
  server.close(async () => {
    logger.info('HTTP server closed');

    try {
      await pool.end();
      logger.info('Database pool closed');
    } catch (err) {
      logger.error('Error closing database pool', { error: err.message });
    }

    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    logger.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

module.exports = app;
```

